from html.parser import HTMLParser
from pathlib import Path
import json
class Player(HTMLParser):
 def __init__(self):super().__init__();self.video=None;self.source=None
 def handle_starttag(self,t,a):
  if t=='video':self.video=dict(a)
  if t=='source':self.source=dict(a)
p=Player();p.feed(Path('index.html').read_text());assert 'controls' in p.video;assert p.source['src']=='video.mp4'
for w,h in [(1920,1080),(1440,900),(390,844),(844,390),(2560,1080)]:
 vw=min(w,h*16/9);vh=min(w*9/16,h);assert abs(vw/vh-16/9)<1e-9
 assert vw<=w and vh<=h
